// Sliding Window Maximum - O(n) using monotonic deque
function maxSlidingWindow(nums, k) {
  const n = nums.length;
  const result = [];
  const deque = []; // stores indices, front = max

  for (let i = 0; i < n; i++) {
    // evict expired elements from the front
    while (deque.length > 0 && deque[0] <= i - k) {
      deque.shift();
    }

    // evict dominated elements from the back
    // (elements smaller than nums[i] can never be max while i is in window)
    while (deque.length > 0 && nums[deque[deque.length - 1]] <= nums[i]) {
      deque.pop();
    }

    deque.push(i);

    // record answer once the first full window is formed
    if (i >= k - 1) {
      result.push(nums[deque[0]]);
    }
  }

  return result;
}

// DP + Monotonic Queue - Jump Game VI style
// dp[i] = max(dp[i-k..i-1]) + nums[i]
function dpWithMonotonicQueue(nums, k) {
  const n = nums.length;
  const dp = new Array(n).fill(0);
  dp[0] = nums[0];
  const deque = [0]; // stores indices of dp values, front = max dp

  for (let i = 1; i < n; i++) {
    // evict dp values outside the window [i-k, i-1]
    while (deque.length > 0 && deque[0] < i - k) {
      deque.shift();
    }
    dp[i] = dp[deque[0]] + nums[i];

    // evict dominated dp values from back before pushing dp[i]
    while (deque.length > 0 && dp[deque[deque.length - 1]] <= dp[i]) {
      deque.pop();
    }
    deque.push(i);
  }

  return dp[n - 1];
}
